void pet_sprites_load_pet(UINT8 idx) NONBANKED {
    UINT8 old_bank = _current_bank;
    if (idx >= 9u) idx = 0;
    SWITCH_ROM_MBC1(10);
    set_sprite_data(PET_SPRITE_BASE, PET_SPRITE_TILES,
                    all_pet_data + (UINT16)idx * 128u);
    SWITCH_ROM_MBC1(old_bank);
}

void pet_sprites_load_preview(UINT8 idx) NONBANKED {
    UINT8 old_bank = _current_bank;
    if (idx >= 9u) idx = 0;
    SWITCH_ROM_MBC1(10);
    set_bkg_data(132u, 4u, all_pet_data + (UINT16)idx * 128u);
    SWITCH_ROM_MBC1(old_bank);
}
